from itertools import product
from math import gcd, comb

def partitions_box(r,c):
    out=[]
    def rec(prefix,last):
        if len(prefix)==r:
            out.append(tuple(prefix)); return
        for x in range(last,-1,-1): rec(prefix+[x],x)
    rec([],c)
    return out

def smith(A):
    A=[row[:] for row in A]
    m=len(A); n=len(A[0]) if m else 0
    i=j=0; diag=[]
    while i<m and j<n:
        pos=None
        for x in range(i,m):
            for y in range(j,n):
                if A[x][y] and (pos is None or abs(A[x][y])<abs(A[pos[0]][pos[1]])):
                    pos=(x,y)
        if pos is None: break
        x,y=pos; A[i],A[x]=A[x],A[i]
        for row in A: row[j],row[y]=row[y],row[j]
        while True:
            changed=True
            while changed:
                changed=False
                for x in range(i+1,m):
                    if A[x][j]:
                        q=A[x][j]//A[i][j]
                        A[x]=[A[x][z]-q*A[i][z] for z in range(n)]
                        if A[x][j]:
                            A[i],A[x]=A[x],A[i]
                        changed=True; break
                if changed: continue
                for y in range(j+1,n):
                    if A[i][y]:
                        q=A[i][y]//A[i][j]
                        for x in range(m): A[x][y]-=q*A[x][j]
                        if A[i][y]:
                            for row in A: row[j],row[y]=row[y],row[j]
                        changed=True; break
            bad=None
            p=abs(A[i][j])
            for x in range(i+1,m):
                for y in range(j+1,n):
                    if A[x][y] % p:
                        bad=(x,y); break
                if bad: break
            if bad is None: break
            x,y=bad
            A[i]=[A[i][z]+A[x][z] for z in range(n)]
        if A[i][j]<0: A[i]=[-z for z in A[i]]
        diag.append(A[i][j]); i+=1; j+=1
    return [d for d in diag if d]

def compute(r,c,i,j):
    P=partitions_box(r,c)
    J=[lam for lam in P if all(lam[q]>=i for q in range(j))]
    ix={lam:q for q,lam in enumerate(J)}
    cols=[]
    for lam in J:
        for k in range(1,r+1):
            col=[0]*len(J)
            for mu in P:
                if sum(mu)-sum(lam)==k and all(mu[q]-lam[q] in (0,1) for q in range(r)):
                    if mu in ix: col[ix[mu]]+=1
            if any(col): cols.append(col)
    A=[[cols[z][q] for z in range(len(cols))] for q in range(len(J))]
    D=smith(A) if cols else []
    rank=len(D); free=len(J)-rank
    tors=[d for d in D if d>1]
    primes=[]
    for d in tors:
        x=d; p=2
        while p*p<=x:
            if x%p==0:
                primes.append(p)
                while x%p==0:x//=p
            p+=1
        if x>1: primes.append(x)
    mu=free+max(([sum(1 for d in tors if d%p==0) for p in set(primes)] or [0]))
    a=min(c-i,r-j); b=min(i,j); N=comb(a+b,a)
    return dict(r=r,c=c,n=r+c,i=i,j=j,a=a,b=b,N=N,Jbasis=len(J),relations=len(cols),rank=free,torsion=tors,mu=mu)

cases=[(4,5,2,2),(5,1,1,1),(5,2,1,1),(1,6,1,1)]
for z in cases: print(compute(*z))
